-- =============================================================================
-- AI Cybersecurity, Governance & Enterprise Compliance — Course Structure
-- 18 modules · 5 lessons each (90 total) · 18 chapter-end quizzes
-- curriculum_version: cyber-v1
-- THE FLAGSHIP: Technical Security + GRC + AI Governance in one program
-- Apply FIRST — before all content, quiz, and simulation migrations
-- Idempotent: safe to re-run
-- =============================================================================

-- 1) Course ──────────────────────────────────────────────────────────────────
DO $$
DECLARE cid uuid;
BEGIN
  SELECT id INTO cid FROM public.courses
    WHERE title = 'AI Cybersecurity, Governance & Enterprise Compliance'
      AND curriculum_version = 'cyber-v1';
  IF cid IS NULL THEN
    INSERT INTO public.courses (title, description, is_published, is_flagship,
        flagship_version, curriculum_version, launch_status,
        target_market, target_salary_low, target_salary_high, translations)
    VALUES (
      'AI Cybersecurity, Governance & Enterprise Compliance',
      'The only program that combines Technical Security + GRC + AI Governance in one career-defining curriculum. 18 modules covering Zero Trust, SOC operations, cloud security, penetration testing, DevSecOps, DFIR, GRC, SOC 2, ISO 27001, GDPR, HIPAA, AI Security, Identity PAM, Threat Intelligence, SOAR, Audit Readiness, CISO Leadership, and an Enterprise Capstone. Aligned to CISSP, CISM, CRISC, CGRC, CCSP, ISO 27001 Lead Implementer, CompTIA Security+/CySA+, and Aladiah AI Security Pro.',
      false, true, 'cyber-v1', 'cyber-v1', 'draft',
      'Security professionals, GRC analysts, compliance managers, IT professionals, and career-changers targeting $95K–$280K cybersecurity roles',
      95000, 280000, '{}'::jsonb
    );
  END IF;
END $$;

-- 2) Module builder helper ──────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION pg_temp.seed_cyber_module(
  p_idx  int,
  p_title text,
  p_desc  text,
  p_pass  int,
  p_l    text[],
  p_ld   text[]
) RETURNS void LANGUAGE plpgsql AS $fn$
DECLARE cid uuid; m_ch uuid; i int;
BEGIN
  SELECT id INTO cid FROM public.courses
    WHERE title = 'AI Cybersecurity, Governance & Enterprise Compliance'
      AND curriculum_version = 'cyber-v1';

  SELECT id INTO m_ch FROM public.chapters WHERE course_id = cid AND order_index = p_idx;
  IF m_ch IS NULL THEN
    INSERT INTO public.chapters (course_id, title, description, order_index, translations)
    VALUES (cid, p_title, p_desc, p_idx, '{}'::jsonb) RETURNING id INTO m_ch;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.videos WHERE chapter_id = m_ch) THEN
    FOR i IN 1 .. array_length(p_l, 1) LOOP
      INSERT INTO public.videos (chapter_id, title, description, order_index, translations)
      VALUES (m_ch, p_l[i], p_ld[i], i, '{}'::jsonb);
    END LOOP;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.quizzes WHERE chapter_id = m_ch AND quiz_type = 'chapter_end') THEN
    INSERT INTO public.quizzes (chapter_id, quiz_type, passing_score)
    VALUES (m_ch, 'chapter_end', p_pass);
  END IF;
END;
$fn$;

-- 3) 18 Modules ──────────────────────────────────────────────────────────────

-- PHASE 1 — TECHNICAL SECURITY CORE

SELECT pg_temp.seed_cyber_module(1, 'Cybersecurity Foundations — CIA Triad & Zero Trust',
  'The bedrock of every cybersecurity career: CIA Triad, Zero Trust architecture, IAM fundamentals, cryptography, PKI, and threat modeling. Every subsequent module builds on these foundations.',
  80,
  ARRAY['CIA Triad — Confidentiality, Integrity & Availability','Zero Trust Architecture — Never Trust, Always Verify','Identity & Access Management (IAM) Fundamentals','Encryption, Cryptography & Public Key Infrastructure (PKI)','Threat Modeling & NIST Security Control Frameworks'],
  ARRAY['The CIA Triad is the foundational model for all security decisions: Confidentiality (protecting data from unauthorized disclosure), Integrity (preventing unauthorized modification), and Availability (ensuring systems are accessible when needed). Every security control maps back to one or more CIA properties.','Zero Trust rejects the assumption that anything inside a network perimeter is safe. Core principle: verify every user, device, and request explicitly; use least-privilege access; assume breach. Architecture: Policy Engine at center, identity as the new perimeter, micro-segmentation, continuous verification.','IAM defines who can access what under which conditions. Core concepts: authentication (proving identity), authorization (what you can do), MFA, RBAC vs ABAC, privilege escalation risks, service accounts, and the principle of least privilege. IAM misconfigurations are the #1 cloud breach vector.','Cryptography protects data in transit and at rest. Symmetric encryption (AES-256), asymmetric encryption (RSA, ECC), hashing (SHA-256, SHA-3), digital signatures, and the PKI chain of trust: Root CA → Intermediate CA → End Entity Certificate. TLS 1.3, certificate lifecycle, and revocation (CRL/OCSP).','Threat modeling identifies threats before they become incidents. STRIDE framework (Spoofing, Tampering, Repudiation, Information Disclosure, Denial of Service, Elevation of Privilege), attack trees, PASTA methodology, and mapping threats to NIST CSF 2.0 control categories: Govern, Identify, Protect, Detect, Respond, Recover.']);

SELECT pg_temp.seed_cyber_module(2, 'Enterprise Security Operations — SOC, SIEM & XDR',
  'How enterprise security teams detect, hunt, and respond to threats in real time: SOC structure, SIEM correlation, XDR/EDR telemetry, threat intelligence feeds, vulnerability management, and the NIST incident response lifecycle.',
  80,
  ARRAY['Security Operations Center (SOC) — Structure, Roles & Tiers','SIEM Mastery — Log Ingestion, Correlation Rules & Alert Triage','XDR & EDR — Endpoint Telemetry, Behavior Analysis & Threat Hunting','Threat Intelligence — STIX/TAXII, IOCs, TTPs & the Intelligence Lifecycle','Incident Response — NIST SP 800-61 & the IR Playbook'],
  ARRAY['A SOC is the 24/7 nerve center of enterprise security. Tier 1 (alert triage), Tier 2 (incident investigation), Tier 3 (threat hunting and forensics), and management layers. Tools stack: SIEM, SOAR, EDR, UEBA, ticketing. Metrics: MTTD (Mean Time to Detect), MTTR (Mean Time to Respond), false positive rate.','SIEM ingests logs from firewalls, servers, endpoints, cloud platforms, and applications — correlating events to surface suspicious patterns. Key skills: writing detection rules, tuning alert thresholds, building dashboards, and performing root-cause analysis. Platforms: Microsoft Sentinel, Splunk, Elastic SIEM, Wazuh.','XDR (Extended Detection & Response) unifies endpoint, network, email, and cloud telemetry into a single investigation surface. EDR tools (CrowdStrike Falcon, Microsoft Defender, SentinelOne) provide process trees, memory scanning, behavioral analysis, and automated containment. Threat hunting: hypothesis-driven search for adversary TTPs before alerts fire.','Threat intelligence transforms raw data into actionable knowledge. Intelligence lifecycle: direction, collection, processing, analysis, dissemination, feedback. IOCs (Indicators of Compromise), TTPs (Tactics, Techniques, Procedures), STIX/TAXII standards, and platforms: Recorded Future, Mandiant Advantage, OpenCTI, MISP.','NIST SP 800-61 defines the IR lifecycle: Preparation → Detection & Analysis → Containment, Eradication & Recovery → Post-Incident Activity. Key artifacts: incident declaration criteria, communication trees, containment playbooks, evidence preservation, eradication verification, and the post-incident review (lessons learned).']);

SELECT pg_temp.seed_cyber_module(3, 'Cloud Security — AWS, Azure, GCP & Container Security',
  'Securing the cloud footprint across all three major platforms plus containers and Kubernetes: IAM least-privilege, CSPM, secrets management, container hardening, and the shared responsibility model.',
  80,
  ARRAY['Cloud Security Fundamentals & Shared Responsibility Model','AWS Security — IAM, GuardDuty, Security Hub, KMS & CloudTrail','Azure Security — Defender for Cloud, Entra ID, Sentinel & Policies','Container Security — Docker Hardening, Image Scanning & Kubernetes RBAC','Cloud CSPM, Secrets Management & Cloud-Native Security Posture'],
  ARRAY['The shared responsibility model defines what the cloud provider secures vs. what the customer secures. AWS/Azure/GCP own the infrastructure; customers own data, identity, and configuration. The #1 cloud breach cause: misconfiguration, not provider vulnerability. CSPM tools continuously audit for drift from security baselines.','AWS security stack: IAM (roles, policies, SCPs for Organizations), GuardDuty (threat detection from CloudTrail/VPC Flow Logs/DNS), Security Hub (compliance aggregation), KMS (key management), CloudTrail (audit logging), and Config (configuration compliance). IAM least-privilege design: never use root credentials, use roles not users, enforce MFA.','Azure security stack: Defender for Cloud (CSPM + workload protection), Entra ID (formerly Azure AD — identity, Conditional Access, PIM), Microsoft Sentinel (SIEM/SOAR), Azure Policy (guardrails), Key Vault (secrets). Entra ID Conditional Access: enforce MFA, device compliance, location, and risk-based authentication.','Container attack surface: image vulnerabilities, secrets in environment variables, root containers, excessive RBAC permissions. Docker hardening: non-root USER, read-only filesystems, no privileged mode, image scanning (Trivy, Snyk). Kubernetes: RBAC configuration, network policies, pod security admission, secret encryption at rest.','CSPM tools (Prisma Cloud, Wiz, AWS Security Hub) continuously scan cloud environments for misconfigurations, over-privileged IAM roles, public S3 buckets, and compliance drift. Secrets management: HashiCorp Vault, AWS Secrets Manager, Azure Key Vault — automated rotation, dynamic secrets, and audit logging for every secret access.']);

SELECT pg_temp.seed_cyber_module(4, 'Network Security & Penetration Testing',
  'A professional penetration tester''s methodology from reconnaissance to report: network attack vectors, the PTES framework, exploitation techniques, post-exploitation, and writing executive-grade pen test reports.',
  80,
  ARRAY['Network Security Fundamentals — Protocols, Attack Vectors & Defense Architecture','Penetration Testing Methodology — PTES, Scoping & Rules of Engagement','Reconnaissance & Vulnerability Assessment — Active & Passive Intelligence','Exploitation, Post-Exploitation & Lateral Movement Techniques','Pen Test Reporting — Executive Summary, Technical Findings & Remediation Roadmap'],
  ARRAY['Network attack surface: TCP/IP weaknesses, ARP spoofing, DNS poisoning, VLAN hopping, BGP hijacking, man-in-the-middle attacks, and packet capture. Defense architecture: network segmentation, DMZ design, firewall rule hierarchies, IDS/IPS placement, network access control (NAC), and micro-segmentation with Zero Trust.','PTES (Penetration Testing Execution Standard) defines seven phases: Pre-engagement, Intelligence Gathering, Threat Modeling, Vulnerability Analysis, Exploitation, Post-Exploitation, and Reporting. Scoping: defining IP ranges, excluded systems, testing windows, emergency contacts, and rules of engagement documentation. Legal authorization is non-negotiable.','Passive reconnaissance (OSINT): Shodan, LinkedIn, WHOIS, certificate transparency logs, Google dorking. Active reconnaissance: Nmap port/service scanning, Nessus/OpenVAS vulnerability scanning, banner grabbing, SMB enumeration. Mapping findings to CVSS scores and exploitability for prioritization.','Exploitation with Metasploit, manual exploitation, and custom payloads. Post-exploitation: privilege escalation (local/domain), credential harvesting (Mimikatz, LSASS dumping), persistence mechanisms, lateral movement (Pass-the-Hash, Pass-the-Ticket, PsExec), and pivoting through network segments. Evidence collection for reporting.','A professional pen test report has two audiences: technical teams (vulnerability details, PoC evidence, specific remediation steps) and executives (risk exposure in business terms, risk-rated finding summary, remediation roadmap with priorities). CVSS scoring, risk ratings (Critical/High/Medium/Low/Info), and a retest verification section.']);

SELECT pg_temp.seed_cyber_module(5, 'Application Security & DevSecOps',
  'Securing software from first commit to production: OWASP Top 10, secure SDLC, SAST/DAST/SCA tooling, API security, threat modeling for applications, and building security into CI/CD pipelines.',
  80,
  ARRAY['Application Security Fundamentals & OWASP Top 10 Web','Secure Software Development Lifecycle (SSDLC) — Security by Design','SAST, DAST & SCA — Automated Security Testing in the Pipeline','API Security — OWASP API Top 10, Authentication & Authorization Flaws','DevSecOps — Shifting Security Left in CI/CD Pipelines'],
  ARRAY['OWASP Top 10 Web (2021): A01 Broken Access Control, A02 Cryptographic Failures, A03 Injection (SQLi, XSS, XXE), A04 Insecure Design, A05 Security Misconfiguration, A06 Vulnerable Components, A07 Authentication Failures, A08 Software & Data Integrity Failures, A09 Logging & Monitoring Failures, A10 SSRF. Each with real exploitation examples and specific mitigations.','Secure SDLC integrates security into every development phase. Security requirements in planning, threat modeling in design, secure coding standards in development, SAST in build, DAST in test, penetration testing before release, and security monitoring in production. BSIMM and OWASP SAMM maturity models for measuring AppSec program effectiveness.','SAST (Static Application Security Testing): Checkmarx, Semgrep, SonarQube — analyze source code without running it. DAST (Dynamic Application Security Testing): OWASP ZAP, Burp Suite — attack running applications. SCA (Software Composition Analysis): Snyk, Dependabot — identify vulnerabilities in open-source dependencies. IAST combines runtime instrumentation with DAST for deeper coverage.','OWASP API Security Top 10: Broken Object Level Authorization (BOLA), Broken Authentication, Broken Object Property Level Authorization, Unrestricted Resource Consumption, Broken Function Level Authorization, Unrestricted Access to Sensitive Business Flows, SSRF, Security Misconfiguration, Improper Inventory Management, and Unsafe Consumption of APIs. API gateway security, OAuth 2.0 flows, JWT hardening.','DevSecOps embeds security into the development pipeline: pre-commit hooks (secrets scanning with Gitleaks/TruffleHog), CI pipeline SAST/SCA gates, container image scanning (Trivy) before deployment, IaC scanning (Checkov, tfsec for Terraform), DAST in staging, runtime protection (WAF, RASP) in production. Security as code: policy-as-code for guardrails.']);

SELECT pg_temp.seed_cyber_module(6, 'Digital Forensics & Incident Response (DFIR)',
  'The science of preserving and analyzing evidence after a breach: chain of custody, disk and memory forensics, network forensics, malware analysis, and writing legally defensible forensic reports.',
  80,
  ARRAY['DFIR Foundations — Evidence Handling, Chain of Custody & Legal Framework','Disk Forensics — Acquisition, File System Analysis & Artifact Recovery','Memory Forensics — Live Analysis, Process Injection & Malware Detection','Network Forensics — Packet Capture, Flow Analysis & C2 Detection','Malware Analysis Fundamentals & DFIR Report Writing'],
  ARRAY['DFIR begins before an incident: documented procedures, pre-authorized forensic tools, and an evidence handling policy. Chain of custody: every piece of evidence must be logged with who collected it, when, where, how, and who has possessed it since. Legal admissibility depends on integrity. Order of volatility: CPU registers → RAM → Network state → Running processes → Disk → Remote logs.','Disk forensics: create a forensic image (dd, FTK Imager, Magnet AXIOM) before examining — never work on the original. File system artifacts: deleted file recovery, MFT (Master File Table) analysis, shellbag artifacts, LNK files, prefetch, Windows Registry hives, browser history, and USB device history. Linux: ext4 journal, bash history, /var/log, cron jobs.','Memory forensics with Volatility3: process listing (pslist, pstree), network connections (netstat), injected code detection (malfind), DLL injection, process hollowing, rootkit detection, and extracting credentials from LSASS. Live memory acquisition: winpmem, LiME. Memory is volatile — capture before rebooting any compromised system.','Network forensics: full packet capture (Wireshark, tcpdump, NetworkMiner), NetFlow/IPFIX analysis, DNS query logs, proxy logs, and firewall logs. Indicators to look for: beaconing patterns (C2 communication), data exfiltration (large outbound transfers), lateral movement (internal port scanning), and anomalous authentication events.','Malware analysis: static (file hashing, PE header analysis, string extraction, YARA rules) and dynamic (sandbox execution in Cuckoo/Any.run, API call monitoring, network traffic capture, registry changes). DFIR report structure: executive summary, timeline of events, technical findings, evidence index, root cause analysis, containment actions taken, and recommendations.']);

-- PHASE 2 — GOVERNANCE, RISK & COMPLIANCE

SELECT pg_temp.seed_cyber_module(7, 'Governance, Risk & Compliance (GRC) Foundations',
  'The complete GRC program from risk registers to board-level reporting: governance frameworks, risk assessment methodology, policy lifecycle, internal controls, security metrics, and building an enterprise security program.',
  80,
  ARRAY['GRC Architecture — Governance, Risk & Compliance Triad','Risk Assessment Methodology — Qualitative, Quantitative & FAIR Model','Risk Register Construction, Treatment Plans & Residual Risk','Security Policy Lifecycle — Creation, Approval, Training & Enforcement','Security Metrics, KPIs & Board-Level Risk Reporting'],
  ARRAY['GRC is the operating system of enterprise security. Governance: how the organization directs security decisions (security committee, CISO reporting structure, board oversight). Risk: identifying, assessing, and treating threats to business objectives. Compliance: ensuring adherence to laws, regulations, and internal policies. Frameworks: COBIT 2019, NIST CSF 2.0, ISO 31000.','Qualitative risk assessment: likelihood × impact matrices (1–5 scale), risk scoring, and heat maps — fast but subjective. Quantitative: annualized loss expectancy (ALE = ARO × SLE), ROI for controls. FAIR (Factor Analysis of Information Risk): the gold standard for quantitative cyber risk — models frequency and magnitude of loss events in financial terms for executive communication.','A risk register documents every identified risk with: risk ID, description, likelihood, impact, risk score, owner, treatment decision (Accept/Mitigate/Transfer/Avoid), mitigation controls, residual risk, and review date. Risk treatment plans specify which controls reduce which risks to what target level. Residual risk is the remaining exposure after controls are applied.','Security policies translate governance decisions into employee obligations. Policy hierarchy: Policy (what) → Standard (how much) → Procedure (how) → Guideline (recommended). Policy lifecycle: draft → legal/HR review → CISO approval → training → communication → enforcement → annual review. Key policies: Acceptable Use, Access Control, Incident Response, Password, Data Classification, Remote Work.','Security metrics communicate risk in business language. Leading indicators: vulnerability age, patch compliance rate, training completion, phishing simulation click rate. Lagging indicators: MTTD, MTTR, breach count, control failure rate. Executive dashboard: top 5 risks, control effectiveness trend, compliance status by framework, security investment ROI.']);

SELECT pg_temp.seed_cyber_module(8, 'SOC 2 Mastery — Trust Service Criteria & Audit Excellence',
  'Complete SOC 2 preparation from Trust Service Criteria deep dive to evidence collection, Type I vs Type II process, working with auditors, and delivering a readiness assessment that gets your company audit-ready in 90 days.',
  85,
  ARRAY['SOC 2 Foundation — The Five Trust Service Criteria & Why They Matter','Common Criteria (CC) — All 9 Categories Deep Dive','Evidence Collection Methodology & Control Mapping to TSC','SOC 2 Type I vs Type II — Audit Process, Timeline & Working with Auditors','System Description Drafting & 90-Day Readiness Sprint'],
  ARRAY['SOC 2 is the security standard for SaaS and service providers. Five Trust Service Criteria: Security (mandatory, CC series), Availability (uptime SLAs), Confidentiality (data protection), Processing Integrity (complete and accurate processing), and Privacy (personal data handling). Type I: controls are designed. Type II: controls operate effectively over a period (typically 6–12 months).','Common Criteria (CC) series covers 9 categories: CC1 (Control Environment — tone from the top), CC2 (Communication & Information), CC3 (Risk Assessment), CC4 (Monitoring), CC5 (Control Activities — policies and procedures), CC6 (Logical and Physical Access), CC7 (System Operations), CC8 (Change Management), CC9 (Risk Mitigation). CC6 and CC7 generate the most evidence.','Evidence collection is the operational core of SOC 2. For each control, auditors request: policy documents, system screenshots, access logs, configuration exports, training records, and signed vendor contracts. Evidence should be timestamped, tied to a specific control ID, and organized in a shared drive or compliance tool (Vanta, Drata, Secureframe). Common gaps: no evidence of control operation, policy exists but is not enforced.','Type I audit: point-in-time snapshot of control design. Type II audit: evidence of control operation over a review period (typically 6–12 months). Auditor interaction: kickoff meeting, evidence requests (PBC list), walkthrough sessions, management letter responses. Auditor mindset: they test controls — not just document existence. Controls that exist on paper but fail in practice produce findings.','The System Description (Section III of SOC 2 report) describes the service organization''s system: principal service commitments, system components, risk assessment process, and control environment. A 90-day readiness sprint: Week 1–2 gap assessment, Week 3–6 control implementation, Week 7–10 evidence collection, Week 11–12 internal readiness review and auditor engagement.']);

SELECT pg_temp.seed_cyber_module(9, 'ISO 27001 — Information Security Management System',
  'The global standard for information security management: ISMS design, the full Annex A control set, Statement of Applicability, internal audit execution, management review, and the certification roadmap from gap to certificate.',
  85,
  ARRAY['ISO 27001:2022 Structure — Clauses 4–10 & the PDCA Model','ISMS Design — Scope, Context, Leadership & Planning','Annex A Controls — All 93 Controls Across 4 Themes','Statement of Applicability (SoA) — Construction & Justification','Internal Audit Planning, NCR Writing & Certification Roadmap'],
  ARRAY['ISO 27001:2022 has 11 clauses. Clauses 1–3 (Introduction, Scope, Terms) set context. Clauses 4–10 are the requirements: 4 (Context), 5 (Leadership), 6 (Planning — risks & objectives), 7 (Support — resources, competence, communication), 8 (Operation), 9 (Performance evaluation), 10 (Improvement). Annex A contains 93 controls in 4 themes. PDCA: Plan (establish) → Do (implement) → Check (monitor/audit) → Act (improve).','ISMS scope defines the organizational boundaries covered by the management system. Scope considerations: which business units, locations, systems, and processes. Context: internal factors (culture, capabilities) and external (regulatory environment, client requirements). Leadership: top management must demonstrate commitment, appoint an ISMS owner, and integrate information security into business processes.','Annex A (2022 edition) reorganized from 114 controls in 14 domains to 93 controls in 4 themes: Organizational (37 controls — policies, roles, vendor management), People (8 controls — vetting, training, disciplinary process), Physical (14 controls — physical access, equipment security), Technological (34 controls — access control, cryptography, network security, incident management). New 2022 controls include threat intelligence, cloud security, and data masking.','The Statement of Applicability is the core ISO 27001 document: for each of the 93 Annex A controls, state whether it is applicable, why (legal, contractual, or risk-based justification), and reference to the evidence of implementation. A control may be excluded only with documented justification. Auditors scrutinize the SoA for logical consistency between scope, risk assessment results, and control selection.','Internal audit methodology: audit program (annual plan), individual audit plans (scope, criteria, methods), audit team (independence requirement), evidence collection (interviews + observation + document review), findings classification (conformity/non-conformity/opportunity for improvement), NCR (Non-Conformity Report) writing, management review input, and corrective action tracking. Stage 1 (documentation review) and Stage 2 (implementation audit) by certification body.']);

SELECT pg_temp.seed_cyber_module(10, 'Privacy Engineering — GDPR, HIPAA & Global Privacy Law',
  'Privacy by design, data subject rights, GDPR obligations, HIPAA technical safeguards, data flow mapping, Privacy Impact Assessments, and navigating the global patchwork of privacy regulations including CCPA and state laws.',
  80,
  ARRAY['Privacy by Design — 7 Principles & Privacy as a Security Discipline','GDPR Deep Dive — Lawful Basis, Data Subject Rights, DPO & Breach Notification','HIPAA Security Rule — PHI, Technical Safeguards & Breach Notification','Data Classification, Flow Mapping & Minimization — Where PII Lives','Privacy Impact Assessment (DPIA) & Global Privacy Landscape — CCPA, LGPD & Beyond'],
  ARRAY['Privacy by Design (Ann Cavoukian, 7 principles): Proactive not Reactive, Privacy as Default, Privacy Embedded into Design, Full Functionality (positive-sum not zero-sum), End-to-End Security, Visibility & Transparency, and Respect for User Privacy. Privacy and security are complementary — a data breach is simultaneously a security failure and a privacy violation. Privacy engineering integrates PbD into architecture decisions.','GDPR (2018, EU): lawful basis for processing (6 bases — consent, contract, legal obligation, vital interests, public task, legitimate interests), data subject rights (access, rectification, erasure/right to be forgotten, portability, restriction, objection, no automated decision-making), DPO (Data Protection Officer) requirement for public authorities and large-scale processing, 72-hour breach notification to supervisory authority, data protection by design and default, and DPA (Data Processing Agreements) with processors.','HIPAA Security Rule protects electronic PHI (ePHI). Technical safeguards: access controls, audit controls, integrity (transmission security), and person or entity authentication. Minimum necessary standard: use only the PHI required for the stated purpose. Business Associate Agreements (BAA): required for any third party handling PHI. Breach notification: within 60 days to affected individuals; annually if <500 records; within 60 days to HHS if >500 records.','Data flow mapping: trace personal data from collection (web forms, APIs, mobile) → storage (databases, cloud, backups) → processing (analytics, ML training) → sharing (third parties, vendors, regulators) → deletion (retention policy, right to erasure). Data classification: Public, Internal, Confidential, Restricted. Minimization: only collect what is needed, retain only as long as needed, delete securely (NIST SP 800-88).','DPIA (Data Protection Impact Assessment) is mandatory under GDPR for high-risk processing: large-scale surveillance, systematic profiling, processing of special categories (health, biometric, racial). DPIA steps: describe processing, assess necessity/proportionality, identify and assess risks, identify measures to address risks. Global landscape: CCPA/CPRA (California), LGPD (Brazil), PDPA (Thailand), PIPL (China), DPDPA (India) — each with unique consent, breach notification, and data residency requirements.']);

SELECT pg_temp.seed_cyber_module(11, 'Third-Party & Vendor Risk Management',
  'The complete vendor risk lifecycle: due diligence, security questionnaires (SIG/CAIQ), risk scoring, contract security clauses, fourth-party risk, continuous monitoring, and running a vendor assessment that protects the organization from supply chain attacks.',
  80,
  ARRAY['Vendor Risk Management Framework — Why Third Parties Are Your Biggest Exposure','Security Questionnaires — SIG Lite, CAIQ & Custom Assessment Design','Risk Scoring Models — Inherent Risk, Residual Risk & Tiering','Contract Security Clauses — DPA, BAA, SLAs, Right to Audit & Breach Notification','Continuous Vendor Monitoring, Fourth-Party Risk & Supply Chain Security (SCRM)'],
  ARRAY['Third-party risk is the #1 source of enterprise data breaches (e.g., SolarWinds, Target/HVAC vendor, MOVEit). The vendor risk lifecycle: identification (what vendors do we use?), classification (what data/access do they have?), assessment (what is their security posture?), approval/rejection, onboarding (contractual controls), monitoring (ongoing), and offboarding (data return/destruction). Vendor tiering: Critical (system access + PII), High (significant data), Medium (limited access), Low (no data access).','SIG (Standardized Information Gathering) questionnaire: covers 19 domains including enterprise security, privacy, data integrity, availability, and compliance. SIG Lite: abbreviated version for lower-tier vendors. CAIQ (Consensus Assessments Initiative Questionnaire): Cloud Security Alliance framework for cloud provider assessments. Custom questionnaires: add organization-specific questions (AI usage policy, subcontractor policy, incident notification timeline). Review process: response validation, evidence requests, and follow-up calls.','Inherent risk: the risk exposure before any controls are applied (determined by data sensitivity × access level × criticality). Residual risk: remaining exposure after the vendor''s controls are applied. Risk scoring model: 1–100 scale with weighted domains. Tier assignment: score 0–40 (Critical/High risk), 41–70 (Medium), 71–100 (Low). BitSight and SecurityScorecard provide continuous external risk scoring based on observable attack surface data.','Contract security clauses are legally enforceable controls. Key clauses: DPA (Data Processing Agreement — GDPR mandatory for processors), BAA (Business Associate Agreement — HIPAA mandatory for PHI handlers), SLAs with security metrics (uptime, incident response time), Right to Audit (annual audit or upon security incident), Sub-processor notification (must notify of new sub-processors), Breach Notification (24–72 hour requirement), Data Return and Destruction (post-contract).','Continuous monitoring: automated vendor security ratings (BitSight, SecurityScorecard) flag SSL certificate expiration, open ports, detected malware, and dark web exposure. Fourth-party risk: your vendor''s vendors. If your payment processor uses a subcontractor who is breached, you bear the exposure. SCRM (Supply Chain Risk Management): NIST SP 800-161, mapping your entire supply chain, and software bill of materials (SBOM) for software vendors.']);

-- PHASE 3 — AI SECURITY & ADVANCED THREATS

SELECT pg_temp.seed_cyber_module(12, 'AI Security & AI Governance',
  'The most advanced AI security curriculum in any program: all 6 AI attack vectors, OWASP Top 10 for LLMs (all 10), NIST AI RMF implementation, ISO 42001 AI Management Systems, Responsible AI, and the EU AI Act — plus building a complete AI governance framework.',
  85,
  ARRAY['AI Attack Taxonomy — Prompt Injection, Model Poisoning, Adversarial Inputs & Model Extraction','OWASP Top 10 for LLMs — All 10 Risks with Real-World Exploitation Examples','NIST AI Risk Management Framework — Govern, Map, Measure & Manage','ISO 42001 — AI Management Systems & Responsible AI Principles','EU AI Act, MLSecOps & Building an Enterprise AI Governance Framework'],
  ARRAY['AI attack surface has 6 primary vectors: (1) Prompt Injection — direct (user manipulates LLM) and indirect (malicious content in retrieved data); (2) Training Data Poisoning — corrupting training data to alter model behavior; (3) Model Extraction — querying API to reconstruct model weights; (4) Adversarial Inputs — crafted inputs that cause misclassification; (5) Membership Inference — determining if specific data was in training set; (6) Model Inversion — extracting sensitive training data from model outputs. MITRE ATLAS maps AI-specific TTPs.','OWASP LLM Top 10 (2025): LLM01 Prompt Injection, LLM02 Sensitive Information Disclosure, LLM03 Supply Chain Vulnerabilities, LLM04 Data and Model Poisoning, LLM05 Improper Output Handling, LLM06 Excessive Agency, LLM07 System Prompt Leakage, LLM08 Vector and Embedding Weaknesses, LLM09 Misinformation, LLM10 Unbounded Consumption. For each: attack scenario, detection indicators, and specific mitigations.','NIST AI RMF has four core functions: GOVERN (establish AI risk governance policies, accountability, and culture), MAP (categorize AI systems by risk context and intended use), MEASURE (quantify and assess AI risks using metrics and tools), MANAGE (prioritize and treat identified AI risks). Profiles: AI RMF Core matched to organizational context. Practical implementation: AI system inventory, risk categorization form, measurement framework, and treatment tracking.','ISO 42001:2023 is the AI Management System standard — the ISO 27001 equivalent for AI. Structure mirrors ISO standards: scope, context, leadership, planning, support, operation, performance evaluation, improvement. Key requirements: AI policy, AI risk assessment process, AI objectives, operational controls for AI development and deployment, and continual improvement. Annex A: AI-specific controls including bias management, transparency, human oversight, and accountability.','EU AI Act (2024): risk-based approach — Unacceptable Risk (banned: social scoring, real-time biometric surveillance), High Risk (regulated: AI in employment, education, critical infrastructure, law enforcement), Limited Risk (transparency obligations: chatbots must disclose AI nature), Minimal Risk (no obligations: spam filters, AI in games). MLSecOps: security in the ML pipeline — data validation, model versioning, adversarial testing before deployment, model monitoring for drift and bias. AI governance framework: AI inventory, use case risk classification, approval workflow, monitoring cadence, and incident response for AI failures.']);

SELECT pg_temp.seed_cyber_module(13, 'Identity Security & Privileged Access Management (PAM)',
  'Identity is the new perimeter: Zero Trust identity architecture, Privileged Access Management solutions, SSO and federation standards, MFA attack patterns, and Identity Governance — the fastest-growing enterprise security discipline.',
  80,
  ARRAY['Zero Trust Identity Architecture — Identity as the New Perimeter','Privileged Access Management (PAM) — CyberArk, BeyondTrust & Delinea','SSO, SAML 2.0, OAuth 2.0, OIDC & Federation Standards Deep Dive','MFA Fatigue Attacks, Conditional Access & Adaptive Authentication','Identity Governance & Administration (IGA) — Lifecycle, Certification & Segregation of Duties'],
  ARRAY['In a Zero Trust architecture, identity replaces the network perimeter as the primary security boundary. Every access request must be verified regardless of network location. Identity pillars: strong authentication (phishing-resistant MFA), device health verification (MDM/EDR compliance), least-privilege access (JIT provisioning), and continuous evaluation (risk-adaptive authentication). Identity threat detection and response (ITDR): detecting credential theft, lateral movement, and privilege escalation through identity signals.','PAM protects the most dangerous accounts in the enterprise: domain admin, root, service accounts, and break-glass accounts. Core PAM capabilities: password vaulting (no human knows privileged credentials — checked out JIT), session recording (every privileged session recorded for forensics), just-in-time access (privileges granted for a specific task then revoked), and privileged user behavior analytics (UEBA for detecting anomalous admin activity). Platforms: CyberArk PAM, BeyondTrust Password Safe, Delinea Secret Server.','SSO federation standards: SAML 2.0 (XML-based, enterprise IdP federation, assertion-based), OAuth 2.0 (authorization framework for API access — 4 grant types: authorization code, implicit, client credentials, device flow), OIDC (OpenID Connect — identity layer on top of OAuth 2.0, returns ID token with user claims), and SCIM (System for Cross-domain Identity Management — automated user provisioning). JWT (JSON Web Token): header, payload, signature — RS256 vs HS256 — common misconfigurations (none algorithm attack, weak signing keys).','MFA fatigue attack (push bombing): attacker with stolen credentials floods victim with MFA push notifications until they accept one. Mitigations: number matching (MFA app shows number that matches login screen), additional context display (show IP/location in push), phishing-resistant MFA (FIDO2/WebAuthn hardware keys, passkeys). Conditional Access policies: enforce MFA based on risk signals (unknown device, unusual location, impossible travel, high-risk user). Azure AD Identity Protection, Okta ThreatInsight, Duo Security.','IGA (Identity Governance and Administration) manages the identity lifecycle: joiner (provision access on hire), mover (modify access on role change), leaver (revoke all access on departure). Access certification: periodic review of user access rights by managers and resource owners. Segregation of Duties (SoD): preventing a single user from having conflicting permissions (e.g., create and approve payment). Role mining: analyzing existing access to design principle-of-least-privilege roles. Platforms: SailPoint, Saviynt, Oracle Identity Governance.']);

SELECT pg_temp.seed_cyber_module(14, 'Threat Intelligence & Advanced Threat Hunting',
  'From IOCs to APT tracking: the full intelligence lifecycle, MITRE ATT&CK deep dive across all 14 tactics, nation-state adversary profiling, hypothesis-driven threat hunting, and integrating threat intelligence into SIEM/SOAR/MDR workflows.',
  80,
  ARRAY['Cyber Threat Intelligence (CTI) Lifecycle — Collection, Analysis & Dissemination','MITRE ATT&CK Framework — All 14 Tactics, Techniques & Sub-Techniques Deep Dive','Nation-State APT Tracking & Adversary Profiling (Russia, China, Iran, North Korea)','Hypothesis-Driven Threat Hunting — Methodology, Hunt Packages & TTP-Based Queries','Threat Intelligence Integration — SIEM Rules, SOAR Playbooks & MDR Feeds'],
  ARRAY['CTI lifecycle: Planning & Direction (what intelligence do we need?), Collection (OSINT, dark web, vendor feeds, ISACs, honeypots), Processing (normalizing, deduplicating, enriching), Analysis (correlating IOCs, TTP mapping, attribution), Production (finished intelligence products — strategic, operational, tactical), Dissemination (sharing with stakeholders), Feedback (measuring effectiveness). Intelligence platforms: Recorded Future, Mandiant Advantage, MISP (open source), OpenCTI, ThreatConnect.','MITRE ATT&CK Enterprise matrix: 14 tactics (Reconnaissance, Resource Development, Initial Access, Execution, Persistence, Privilege Escalation, Defense Evasion, Credential Access, Discovery, Lateral Movement, Collection, Command & Control, Exfiltration, Impact) × 193 techniques × 411 sub-techniques. Navigator for heat-mapping adversary coverage. ATT&CK for detection engineering: mapping each technique to SIEM detection rules and EDR queries.','APT groups by nation-state sponsor: Russia (APT28/Fancy Bear, APT29/Cozy Bear, Sandworm — focus: government, defense, energy, election interference); China (APT41, APT10, Volt Typhoon — focus: IP theft, supply chain, critical infrastructure pre-positioning); Iran (APT33/Elfin, APT34/OilRig, APT35 — focus: energy, financial, regional geopolitics); North Korea (Lazarus Group, APT38 — focus: financial theft, cryptocurrency, defense). TTPs, malware families, and infrastructure patterns for each.','Threat hunting methodology: hypothesis generation (based on CTI, ATT&CK coverage gaps, or environmental anomalies), hunt design (what data sources, what queries, what time window), execution (SIEM queries, EDR hunts, network log analysis), analysis (correlating findings, differentiating true positives from noise), documentation (hunt report, new detections, lessons learned). Example hunt: hunting for Kerberoasting (searching for TGS requests for service accounts, then correlating with offline cracking indicators).','Integration architecture: CTI platform → SIEM (automated IOC ingestion into detection rules), SOAR (automated enrichment and response for IOC-matched alerts), TIP (Threat Intelligence Platform) as single source of truth, and MDR (Managed Detection & Response) feeds. STIX/TAXII: standard format and transport for sharing threat intelligence. ISAC participation (FS-ISAC for financial, H-ISAC for healthcare) for sector-specific intelligence.']);

SELECT pg_temp.seed_cyber_module(15, 'Security Automation, SOAR & Compliance Tools',
  'Automating the security program at enterprise scale: compliance automation platforms (Vanta, Drata), SOAR playbook design, Policy-as-Code with Open Policy Agent, infrastructure scanning, and building Python compliance pipelines that collect evidence from hundreds of cloud services.',
  80,
  ARRAY['Compliance Automation Platforms — Vanta, Drata, Secureframe & Evidence Collection at Scale','SOAR Architecture — Playbook Design, Orchestration & Automated Response','Policy Validation as Code — Open Policy Agent (OPA) & Rego Language','Cloud Infrastructure Scanning — Prowler, ScoutSuite, AWS Config & Azure Policy','Building Compliance Pipelines with Python, APIs & CI/CD Integration'],
  ARRAY['Compliance automation platforms connect to cloud services, developer tools, and HR systems to continuously collect evidence. Vanta: integrates with AWS, GCP, Azure, GitHub, Okta, Slack, Jira, Google Workspace, and 200+ more — auto-collects evidence for SOC 2, ISO 27001, HIPAA, GDPR. Drata: similar breadth, strong for security questionnaire automation. Secureframe: strong for FedRAMP. Evidence collection workflow: integration → continuous monitoring → automated evidence tagging → compliance framework mapping → auditor access portal. Reduces manual evidence collection from weeks to hours.','SOAR (Security Orchestration, Automation & Response) platforms (Splunk SOAR, Palo Alto XSOAR, Swimlane) automate repetitive analyst tasks. Playbook design: trigger (SIEM alert, email, API) → enrichment (VirusTotal, Shodan, internal CMDB) → decision logic (if severity = Critical and asset = production) → response actions (isolate endpoint, block IP, create Jira ticket, notify Slack) → documentation (auto-close ticket with evidence). MTTR improvement: from hours to minutes for known attack patterns.','Open Policy Agent (OPA) is the standard for policy-as-code. Rego language defines policies as machine-executable rules. Use cases: Kubernetes admission control (deny pods running as root), Terraform plan validation (block public S3 buckets before deployment), API authorization (RBAC decisions as code), CI/CD gates (block merges that fail security checks). Policy library: pre-built policies for CIS benchmarks, PCI DSS, HIPAA, and SOC 2 controls.','Cloud infrastructure scanning: Prowler (AWS/Azure/GCP open-source CSPM — maps findings to CIS, NIST, SOC 2, ISO 27001, PCI DSS), ScoutSuite (multi-cloud audit tool), AWS Config (continuous configuration recording + compliance rules — e.g., detect unencrypted EBS volumes, open security groups), Azure Policy (enforce guardrails at subscription level — deny non-compliant resources). Scheduled scanning: daily reports with severity-triaged findings, integration with ticketing for remediation tracking.','Python automation for compliance: boto3/azure-sdk/google-cloud to query cloud APIs for configuration state, GitHub API for access reviews and branch protection status, Okta API for MFA enrollment reports, Slack API for security policy acknowledgment tracking. Build an evidence collection pipeline: scheduled Lambda/Cloud Function → query APIs → transform to evidence format → upload to S3/GCS with timestamp → notify compliance platform. Output: automated weekly security posture report with PDF generation.']);

-- PHASE 4 — LEADERSHIP & MASTERY

SELECT pg_temp.seed_cyber_module(16, 'Audit Readiness & Executive Communication',
  'Preparing for and surviving external audits while mastering the executive communication skills that separate security practitioners from security leaders: internal audit methodology, evidence organization, control testing, and delivering board-level risk presentations.',
  80,
  ARRAY['Internal Audit Methodology — Planning, Fieldwork, Findings & Reporting','External Audit Preparation — The Auditor''s Mindset & What They Actually Test','Evidence Mapping, Control Testing & Gap Remediation Tracking','Executive Security Dashboard Design — The Metrics That Move Decisions','Board-Level Risk Presentations & Security Committee Communication'],
  ARRAY['Internal audit methodology (ISO 19011): audit program (annual schedule), audit plan (scope, objectives, criteria, team), fieldwork (interviews + observation + document review + technical testing), findings classification (conformity, minor non-conformity, major non-conformity, observation), audit report (findings, root causes, corrective actions required), and management review input. Audit independence: the internal auditor must not audit their own work. Corrective action plan (CAP) tracking with due dates and ownership.','External auditors are professionals trained to find gaps. They test two things: design effectiveness (is the control designed to achieve the intended objective?) and operating effectiveness (is the control actually working as designed, consistently, over time?). Common audit findings: evidence of control operation is missing for the review period, policy approved but no evidence of training/acknowledgment, access reviews not completed on schedule, change management bypassed for urgent deployments, and vendor risk assessments overdue.','Evidence mapping spreadsheet: Control ID → Control Description → Evidence Type → Evidence Location → Evidence Period → Last Updated → Status (Green/Yellow/Red) → Owner → Auditor Request Reference. Control testing: sample selection (auditors test a statistical sample of events — typically 25–60 samples for high-frequency controls), attribute testing (pass/fail for each sample), and exception investigation. Gap remediation: prioritize by audit risk (major NC vs minor NC), assign owner, set deadline, verify closure with evidence.','Executive security dashboard elements: (1) Risk posture score (trending up/down), (2) Top 5 current risks with heat map, (3) Critical vulnerabilities open >30 days, (4) Compliance status by framework (% controls passing), (5) Incident summary (count, severity, MTTD/MTTR), (6) Security investment vs. breach cost avoided, (7) Training completion rate. Tools: PowerBI, Tableau, or Grafana for live dashboards fed by security tool APIs.','Board presentations: 10-slide maximum, no jargon, lead with business impact not technical details. Structure: (1) Security posture in one sentence, (2) Top 3 risks in business terms (what is the financial/reputational exposure?), (3) What we did this quarter, (4) What we are asking for (budget, headcount, policy decision), (5) Next quarter priorities. Security committee: monthly cadence, CISO chairs, business unit representatives, legal and compliance present. Use the ''newspaper test'': if this incident happened, what would the headline be?']);

SELECT pg_temp.seed_cyber_module(17, 'Security Leadership & CISO Track',
  'The path to CISO: building and managing a security team, security program strategy and budget justification, technology roadmap, vendor management at the C-suite level, and crisis communication when a major breach hits the front page.',
  80,
  ARRAY['The CISO Role — Responsibilities, Authority, Board Reporting & Organizational Structure','Building & Managing a Security Team — Hiring, Structure, Culture & Retention','Security Program Strategy, Budget Justification & ROI Communication','Security Technology Roadmap & Vendor Management at the C-Suite Level','Crisis Leadership — Communicating During a Major Breach & Reputation Management'],
  ARRAY['The modern CISO sits at the intersection of technology, business, and risk. Responsibilities: enterprise security strategy, board and executive reporting, regulatory compliance oversight, security budget ownership, incident response authority, and vendor risk governance. Two reporting models: CISO → CTO (technical alignment) vs. CISO → CEO/CFO/CLO (business alignment). Board relationship: CISO typically presents to the board''s Audit & Risk Committee quarterly. Key stakeholders: CEO (business risk framing), CFO (budget and ROI), CLO (legal and regulatory exposure), CTO (technical alignment), business unit leaders (risk tolerance negotiation).','Security team structure: governance (GRC analysts, compliance managers), operations (SOC analysts, IR team), architecture (security architects, cloud security engineers), and engineering (AppSec, DevSecOps). Hiring: cybersecurity talent shortage — 3.5M unfilled positions globally. Strategies: hire for mindset and train for skills, build development programs, consider MSSPs for Tier 1 SOC, build a cyber range for internal training. Team culture: psychological safety for incident reporting, blameless post-mortems, continuous learning budget, conference attendance (DEF CON, Black Hat, RSA). Retention: compensation benchmarking, visible career progression, recognition.','Security budget justification: frame security spend in terms of risk reduction. ROSI (Return on Security Investment) = (Risk Reduced × Asset Value) − Control Cost. Budget components: people (typically 40–50%), technology (30–40%), training and certifications (5–10%), consulting and audit (5–10%). Budget request structure: current risk posture, proposed investments, expected risk reduction (quantified), regulatory exposure if not funded, and comparison to industry benchmarks (% of IT spend on security: 5–15% depending on sector). Use FAIR model outputs to support budget requests.','Security technology roadmap: 3-year view across five pillars — Identity Security, Cloud Security, Data Security, Endpoint/Network Security, and GRC/Compliance. Vendor management: RFP process, vendor scoring (technical capability × support quality × roadmap alignment × total cost × security posture), contract negotiation (SLAs with financial penalties, right to audit, security incident notification), and annual vendor business reviews. Technology consolidation: the average enterprise has 45+ security tools — platform consolidation (Microsoft Security, Palo Alto Cortex, CrowdStrike) reduces complexity and cost while improving integration.','When a major breach occurs, the CISO faces simultaneous pressure from: the incident response team (containment decisions), legal counsel (privilege protection, breach notification obligations), the board (status updates), and potentially regulators and media. Crisis communication principles: (1) Acknowledge quickly, (2) Provide facts you are certain of, (3) Do not speculate, (4) Assign a single spokesperson, (5) Coordinate with legal before any external statement, (6) Maintain a communications log. Notification obligations: GDPR 72-hour rule, SEC material breach disclosure (4 business days for public companies), state breach notification laws, HIPAA 60-day rule. Post-breach: reputation recovery through demonstrated remediation.']);

SELECT pg_temp.seed_cyber_module(18, 'Enterprise Capstone — Full Security Engagement',
  'The real consulting engagement: students inherit a fictional enterprise with a CEO mandate to achieve SOC 2, ISO 27001, GDPR compliance, AI governance, and vendor management — and present all six workstreams to a panel of CEO, CISO, auditor, and board member.',
  85,
  ARRAY['Capstone Brief — The CEO Mandate & Full Enterprise Stack Assessment','Technical Security Posture Review — Gap Analysis Across All Domains','GRC Program Build — Risk Register, Policy Library & Control Evidence Package','AI Governance, Identity Security & Vendor Risk Deliverables','Board Presentation & AI Security Pro Certification Portfolio'],
  ARRAY['Capstone context: TechNova Financial, a $200M SaaS fintech company, has received notice from their largest enterprise client that SOC 2 Type II certification is required to renew a $15M contract. The CEO mandates: achieve SOC 2 Type II, ISO 27001 certification, GDPR compliance, AI governance for the customer-facing LLM chatbot, and vendor risk program — all within 6 months. Students receive a full enterprise stack: AWS + Azure + M365 + GitHub + Docker + Slack + Salesforce + 3 third-party vendors processing PII. This capstone mirrors real consulting engagement at Big 4 and boutique advisory firms.','Technical security gap analysis: assess Zero Trust maturity (are all access requests verified?), cloud security posture (CSPM findings across AWS/Azure), network segmentation (is there east-west lateral movement protection?), application security (SAST/DAST in CI/CD?), endpoint security (EDR deployed and monitored?), identity security (MFA enforced, PAM in place?), logging and monitoring (SIEM coverage, detection rules). Output: security gap matrix with risk rating, effort to remediate, and priority order.','GRC program build: (1) Risk register — top 15 enterprise risks with likelihood/impact/treatment for each; (2) Policy library — 10 policies: Acceptable Use, Access Control, Incident Response, Data Classification, Password/Authentication, Remote Work, Vendor Risk, Change Management, Data Retention, AI Governance; (3) Control matrix — 30 controls mapped to SOC 2 TSC and ISO 27001 Annex A; (4) Evidence package — organized evidence folder per control with timestamped screenshots, configuration exports, and signed policy acknowledgments. Timeline: which controls close in 30/60/90 days.','AI governance deliverable: threat model the LLM chatbot against OWASP LLM Top 10, AI risk assessment using NIST AI RMF, governance policy (permitted use cases, prohibited uses, human oversight requirements, model monitoring cadence), and EU AI Act risk classification. Identity security deliverable: PAM implementation plan for 12 privileged accounts, IGA role matrix for 200 users, MFA enforcement plan. Vendor risk deliverable: completed SIG assessments for 3 vendors, risk scorecard with tiering, contract security clause recommendations, and ongoing monitoring plan.','Board presentation (15 minutes + Q&A): (1) Executive summary — where TechNova stands today vs. where it needs to be; (2) Top 5 risks in financial terms; (3) 6-month roadmap with milestones and investment required; (4) Quick wins already implemented; (5) Questions from simulated board panel. Portfolio assembly: all 6 workstream deliverables organized as a professional consulting package. AI Security Pro certification: awarded upon successful capstone presentation demonstrating mastery across all 4 phases of the program.']);

